@Component("sensorInstance-handler")
@ProcessingGroup("sensorInstance-processing-group")
public class SensorInstanceEventHandler {
	
	// core constructor
	SensorInstanceEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateSensorInstanceEvent
     */
    @EventHandler
    public void handle( CreateSensorInstanceEvent event) {
        entityManager.persist(new SensorInstance(event.getSensorInstanceId(), event.getName(), event.getUnit(), event.getSamplingIntervalMs(), event.getDevice(), event.getTelemetryStreams(), event.getSensorType()));
    }

    /*
     * @param	event UpdateSensorInstanceEvent
     */
    @EventHandler
    public SensorInstance handle( UpdateSensorInstanceEvent event) {
    	entityManager.merge(new SensorInstance(event.getSensorInstanceId(), event.getName(), event.getUnit(), event.getSamplingIntervalMs(), event.getDevice(), event.getTelemetryStreams(), event.getSensorType()));
    }
    
    /*
     * @param	event DeleteSensorInstanceEvent
     */
    @EventHandler
    public void on( DeleteSensorInstanceEvent event) {
    	SensorInstance entity = new SensorInstance();
   
    	// ------------------------------------------
    	// apply the SensorInstanceId
    	// ------------------------------------------
    	entity.setSensorInstanceId( event.getSensorInstanceId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final SensorInstanceRepository sensorInstanceEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(SensorInstanceEventHandler.class.getName());

}
